<script setup lang="ts">import { computed } from 'vue'; import { useAppStore } from '@/stores/app'; import StatusBadge from '@/components/common/StatusBadge.vue'; import Avatar from '@/components/common/Avatar.vue'; import type { Project, TaskStatus } from '@/types'; const props=defineProps<{project:Project}>(); const app=useAppStore(); const columns:TaskStatus[]=['Backlog','To do','In progress','Review','Done']; const byStatus=(s:TaskStatus)=>app.tasks.filter(t=>t.projectId===props.project.id&&t.status===s); function move(id:string,status:TaskStatus){app.updateTask(id,{status})}</script>
<template><div class="board"><section v-for="status in columns" :key="status" class="board-column"><header><span>{{status}}</span><b>{{byStatus(status).length}}</b></header><div class="board-cards"><article v-for="task in byStatus(status)" :key="task.id" class="board-card"><RouterLink :to="`/tasks/${task.id}`"><small>{{task.key}}</small><h3>{{task.title}}</h3><div class="board-card-footer"><span class="priority" :data-priority="task.priority.toLowerCase()">{{task.priority}}</span><Avatar v-if="task.assignee" :initials="task.assignee.initials" size="sm"/></div></RouterLink><select :value="task.status" @change="move(task.id,($event.target as HTMLSelectElement).value as TaskStatus)"><option v-for="s in columns" :key="s">{{s}}</option></select></article></div></section></div></template>
